+/**
+ * Sanitize an SVG string or DOM element to prevent XSS attacks.
+ * Removes dangerous elements and attributes from SVG content.
+ */
+
+/**
+ * List of SVG/HTML elements that are not allowed (could execute scripts).
+ */
+const DISALLOWED_ELEMENTS = new Set([
+    'script',
+    'object',
+    'embed',
+    'link',
+    'style',
+    'iframe',
+    'frame',
+    'frameset',
+    'applet',
+    'meta',
+    'base',
+    'form',
+    'input',
+    'button',
+    'textarea',
+    'select',
+    'option'
+]);
+
+/**
+ * Pattern matching dangerous attribute names (event handlers and javascript: URLs).
+ */
+const DANGEROUS_ATTR_PATTERN = /^on/i;
+
+/**
+ * Pattern matching dangerous attribute values containing javascript: or data: URIs.
+ */
+const DANGEROUS_VALUE_PATTERN = /^\s*javascript:/i;
+
+/**
+ * Attributes that can contain URLs and need to be checked for dangerous values.
+ */
+const URL_ATTRIBUTES = new Set([
+    'href',
+    'xlink:href',
+    'src',
+    'action',
+    'formaction'
+]);
+
+/**
+ * Recursively sanitize an SVG DOM element in place.
+ * @param {Element} element - The element to sanitize.
+ */
+const sanitizeElement = function (element) {
+    // Collect children to remove (can't modify NodeList while iterating)
+    const toRemove = [];
+    for (let i = 0; i < element.childNodes.length; i++) {
+        const child = element.childNodes[i];
+        if (child.nodeType === child.ELEMENT_NODE) {
+            const tagName = child.tagName && child.tagName.toLowerCase();
+            if (DISALLOWED_ELEMENTS.has(tagName)) {
+                toRemove.push(child);
+            } else {
+                // Sanitize attributes
+                const attrsToRemove = [];
+                for (let j = 0; j < child.attributes.length; j++) {
+                    const attr = child.attributes[j];
+                    const attrName = attr.name.toLowerCase();
+                    const attrValue = attr.value;
+                    // Remove event handler attributes (onclick, onload, etc.)
+                    if (DANGEROUS_ATTR_PATTERN.test(attrName)) {
+                        attrsToRemove.push(attr.name);
+                    // Remove javascript: URLs from href/src/etc.
+                    } else if (URL_ATTRIBUTES.has(attrName) && DANGEROUS_VALUE_PATTERN.test(attrValue)) {
+                        attrsToRemove.push(attr.name);
+                    }
+                }
+                for (const attrName of attrsToRemove) {
+                    child.removeAttribute(attrName);
+                }
+                // Recurse into children
+                sanitizeElement(child);
+            }
+        }
+    }
+    for (const child of toRemove) {
+        element.removeChild(child);
+    }
+};
+
+/**
+ * Sanitize an SVG DOM element to remove potentially dangerous content.
+ * Modifies the element in place.
+ * @param {SVGElement} svgElement - The root SVG element to sanitize.
+ * @returns {SVGElement} The sanitized SVG element.
+ */
+const sanitizeSvg = function (svgElement) {
+    sanitizeElement(svgElement);
+    return svgElement;
+};
