+                .and_then(|v| v.as_u64())
+                .unwrap_or(u64::MAX);
+
+            let status = tcb_level
+                .get("tcbStatus")
+                .and_then(|v| v.as_str())
+                .unwrap_or("Revoked");
+
+            if isv_svn as u64 >= level_svn {
+                // Found the matching TCB level
+                match status {
+                    "UpToDate" | "SWHardeningNeeded" | "ConfigurationNeeded"
+                    | "ConfigurationAndSWHardeningNeeded" => {
+                        found_acceptable = true;
+                        break;
+                    }
+                    "OutOfDate" | "OutOfDateConfigurationNeeded" => {
