+                    }
+                    _ => {
+                        bail!("Unknown QE TCB status: {}", status);
+                    }
+                }
+            }
+        }
+
+        if !found_acceptable {
+            bail!(
+                "No acceptable QE TCB level found for ISV SVN: {}",
+                isv_svn
+            );
+        }
+    }
+
